$(document).ready(function () {
  var lastScrollTop = 0;
  $(window).scroll(function () {
    var scrollTop = $(this).scrollTop();

    if (scrollTop > lastScrollTop && scrollTop >= 10) {
      // Scrolling down
      $(".header__navbar__wrapper")
        .addClass("scroll-down")
        .removeClass("scroll-up");
    } else if (scrollTop < lastScrollTop) {
      // Scrolling up
      $(".header__navbar__wrapper")
        .addClass("scroll-up")
        .removeClass("scroll-down");
    } else if (scrollTop < 10) {
      $(".header__navbar__wrapper").removeClass("scroll-down scroll-up");
    }

    lastScrollTop = scrollTop;
  });
});

let index;
firstenable(1);
$(".myBtn").mouseover(function () {
  var elmId = $(this).attr("id");
  //console.log(elmId.split("-"));
  index = elmId.split("-")[1];

  firstenable(index);
});

function firstenable(index) {
  $(".sub_list_cards_wrap").css("display", "none");
  $(".myBtn").css("color", "#74726B");

  $("#wrap-" + index).css({
    display: "block",
  });

  $("#hover-" + index).css("color", "#ddddda");
}

