// Brainery Section Swiper Initialization
if ($('.brainery-swiper').length) {
  const brainerySwiper = new Swiper('.brainery-swiper', {
    loop: true,
    autoplay: {
      delay: 3000,
      disableOnInteraction: false,
    },
    pagination: {
      el: '.brainery-pagination',
      clickable: true,
    },
  });
}

// Numbers Section Counter Animation
document.addEventListener('DOMContentLoaded', () => {
    const numSection = document.querySelector('.num_section');
    if (!numSection) return;

    const counters = numSection.querySelectorAll('.counterTxt');
    
    const countUp = (entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                counters.forEach(counter => {
                    const target = parseInt(counter.innerText);
                    const duration = 2000;
                    const startTime = performance.now();
                    
                    const updateCount = (currentTime) => {
                        const elapsed = currentTime - startTime;
                        const progress = Math.min(elapsed / duration, 1);
                        
                        // Ease out quad
                        const easeProgress = progress * (2 - progress);
                        const currentCount = Math.floor(easeProgress * target);
                        
                        counter.innerText = currentCount;
                        
                        if (progress < 1) {
                            requestAnimationFrame(updateCount);
                        } else {
                            counter.innerText = target;
                        }
                    };
                    
                    requestAnimationFrame(updateCount);
                });
                // Once triggered, unobserve the section
                observer.unobserve(numSection);
            }
        });
    };

    const observer = new IntersectionObserver(countUp, {
        threshold: 0.2 // Trigger when 20% of section is visible
    });

    observer.observe(numSection);
});

